macro_rules! min_of {
    ($x:expr) => { $x };
    ($x:expr, $($rest:expr),+) => {{
        let a = $x;
        let b = min_of!($($rest),+);
        if a < b { a } else { b }
    }};
}

unitTests:
test("smallest", || {
    check_eq(min_of!(7), 7);
    check_eq(min_of!(3, 9, -4, 7), -4);
    check_eq(min_of!(2.5, 1.5), 1.5);
    check_eq(min_of!("pear", "apple", "fig"), "apple");
});

test("each argument evaluated once", || {
    let mut calls = 0;
    let mut next = |v: i32| { calls += 1; v };
    let m = min_of!(next(5), next(2), next(8));
    check_eq(m, 2);
    check_eq(calls, 3);
});

